"""Turn assets/route-px.json into assets/route-data.js so the composition reads it without a fetch."""
import json, pathlib

assets = pathlib.Path(__file__).parent.parent / "header-video" / "assets"
data = json.loads((assets / "route-px.json").read_text())
(assets / "route-data.js").write_text(
    "// Generated by header-video-src/build_route_js.py from route-px.json. Do not edit.\n"
    "window.CT_ROUTE = " + json.dumps(data, separators=(",", ":")) + ";\n")
print("wrote", assets / "route-data.js")
